package guidancecontent

import (
	"github.com/jaxxstorm/fed/internal/readiness"
	"io/fs"
)

// VDR returns drafts for the complete 147-variant detection/response batch.
func VDR(rules, markdown fs.FS) (readiness.Package, error) {
	return cdvBuild(rules, markdown, "VDR", "vulnerability-detection-and-response", map[string]cdvRecipe{
		"VDR-CSO-DET": {
			"Discover vulnerabilities through an operating detection program that also verifies and validates resource/process behavior.", "Provider vulnerability detection lead and resource owners",
			"The offering's information resources and processes, including non-machine resources and documented FedRAMP Practices; appropriate techniques depend on the service rather than a mandated scanner list.",
			"Map information resources and documented Practices to detection methods and owners. Identify scanning, assessment, threat-intelligence, disclosure, testing and other relevant inputs and how verification and validation are performed.",
			"Discover and identify vulnerabilities systematically, persistently and promptly using appropriate techniques; repeatedly verify and validate that resources and processes operate as intended and documented. Route detected failures into response.",
			"resource/process coverage map, detection-method rationale, dated execution and findings, verification/validation results, current activity status and intentional cycle interruptions.",
			"Compare the resource/process inventory with executed detection and verification/validation records. Examine prompt handling of findings, repeated operation and gaps in methods or coverage; do not equate a clean scan with all-resource assurance.",
			"A scanner license, a clean host scan or a policy promising future detection without process validation, resource coverage and repeated operation.",
		},
		"VDR-CSO-RES": {
			"Manage every detected vulnerability through evaluation, response and defensible disposition.", "Provider vulnerability response lead",
			"All detected vulnerabilities in the offering, including process failures; track, evaluate, monitor, mitigate, remediate, assess exploitation and report as appropriate to each vulnerability's state.",
			"Reconcile detection sources to a response register with stable identifiers, assigned owners, state transitions and links to evaluation, exploitation assessment and reporting records.",
			"Systematically, persistently and promptly manage detected vulnerabilities, retaining the history of evaluation, monitoring, mitigations/remediation, exploitation assessment and reporting rather than closing findings solely because a ticket exists. When full mitigation or remediation is impossible, the source note recommends partial mitigation promptly, progressively and persistently; retain successive evaluated reductions. Full mitigation leaves the vulnerability present; remediation eliminates it.",
			"detection-to-register reconciliation, vulnerability histories, owner assignments, evaluations, monitoring results, mitigation/remediation evidence, exploitation assessments and report references.",
			"Trace findings from detection through actual response actions and disposition; check all named response activities, current status, repeated management and prompt handling, including unresolved items.",
			"A remediation dashboard without source reconciliation, exploitation assessment, reporting or the history supporting closure.",
		},
		"VDR-CSO-FAV": {
			"Bring failures of the detection and response machinery into the vulnerability lifecycle.", "Provider vulnerability operations owner",
			"Problems or failures in vulnerability detection and response processes, including broken collection, missed evaluation and failed response paths.",
			"Identify detection/response process-health signals and the route for registering process failures as vulnerabilities.",
			"Treat discovered process problems and failures as vulnerabilities; create traceable vulnerability records and manage them through the response process.",
			"process failure observations, linked vulnerability identifiers, evaluation/response history and evidence supporting restoration or ongoing disposition.",
			"Reconcile known process failures with vulnerability records; check that failures are not hidden as operational maintenance outside the response population.",
			"A pipeline failure log with no vulnerability tracking or a claim of no findings while the detector was inoperative.",
		},
		"VDR-CSO-DFR": {
			"Reduce vulnerability exposure and response complexity through default design choices.", "Provider security architect and engineering owner",
			"Offering design and architecture decisions affecting default vulnerability risk and the risk/complexity of detection and response; this is a SHOULD recommendation.",
			"Identify architectural decision points, default configurations and detection/response dependencies that make vulnerabilities easier to introduce or harder to manage.",
			"Evaluate design alternatives for both default vulnerability-risk mitigation and reduced detection/response risk and complexity. Record chosen defaults and the rationale for tradeoffs.",
			"architecture decision records, default configuration versions, threat/risk analysis and detection/response workflow comparisons.",
			"Compare implemented defaults with the decisions and assess both halves of the rule; a feature that reduces attack surface but obscures detection needs an explicit tradeoff assessment.",
			"A high-level architecture diagram that does not explain default risk reduction or detection/response complexity.",
		},
		"VDR-CSO-ADT": {
			"Use automation to make vulnerability detection and response more effective and manageable.", "Provider security automation owner",
			"Detection and response workflows suitable for automation within the offering; automated services are recommended, not a specific tool purchase.",
			"Map detection/response workflow bottlenecks to candidate automated services and define the handoffs, failure signals and responsible operators.",
			"Use selected automation to improve and streamline detection and response, retain execution outcomes and handle automation failures through the vulnerability process.",
			"workflow-to-automation mapping, service/configuration versions, execution and failure records, handoff results and rationale for remaining manual activity.",
			"Trace automated outputs into actual detection or response decisions and evaluate how they improve the workflow, including missed runs and failed handoffs.",
			"A configured integration or automation purchase with no executed detection/response results.",
		},
		"VDR-CSO-DAC": {
			"Detect vulnerabilities automatically when new or significantly changed resources enter the offering.", "Provider change owner and detection engineer",
			"Representative samples of new or significantly changed information resources, with a justified link between the changed population and sampled members.",
			"Connect resource creation and significant-change records to automated detection triggers; define representative sampling groups and record why samples represent each changed population.",
			"Automatically perform detection on representative samples when resources are new or significantly changed; retain change identifiers, selected samples and detection outcomes.",
			"creation/change population, significant-change determinations, sampling rationale, trigger configuration and executed detection results tied to the changes.",
			"Reconcile new/significantly changed resources to executed automated detection and verify representativeness; identify changes that bypassed the trigger.",
			"A scheduled scan with no relationship to new or changed resources, or samples chosen solely because they are easy to scan.",
		},
		"VDR-CSO-MSP": {
			"Preserve resource security while enabling detection and assessment.", "Provider assessment coordinator and resource security owner",
			"Security-affecting changes made to facilitate scanning, vulnerability detection or assessment; the rule says SHOULD NOT weaken security.",
			"Identify scanner/assessor access requirements and proposed security configuration changes; compare less-weakening access methods.",
			"Evaluate and avoid security weakening for scanning/detection/assessment; record any departure from SHOULD NOT with its actual security effects and rationale.",
			"assessment access design, before/after security configurations, access grants, change decisions and evidence of the actual assessment mode.",
			"Compare actual security configuration during assessment with the baseline; examine changed protections instead of inferring safety from a successful scan.",
			"A clean scan that depended on disabled protections, with no assessment of the security weakening.",
		},
		"VDR-CSO-AKE": {
			"Avoid introducing known exploited vulnerabilities with newly activated machine resources.", "Provider release owner and vulnerability lead",
			"New machine-based information resources at deployment or other activation; evaluate Known Exploited Vulnerabilities rather than all vulnerabilities indiscriminately.",
			"Map candidate images, components and resources to relevant KEV intelligence and deployment/activation decision points.",
			"Check candidates for known exploited vulnerabilities before deployment or activation and avoid activating affected new resources under the SHOULD NOT rule; preserve decisions and any departures.",
			"candidate resource/component versions, KEV source/date, applicability matches, deployment decisions and actual activation records.",
			"Compare KEV knowledge at the decision time with the versions actually activated; distinguish deployment prevention from later remediation.",
			"A current scan after deployment or a KEV feed with no match to the activated resource versions.",
		},
		"VDR-CSO-SIR": {
			"Use sampling only when equivalent resources and detection outcomes justify it.", "Provider detection methodology owner",
			"Effectively identical information resources, especially machine-based resources; sampling is permitted UNLESS it decreases detection efficiency or effectiveness.",
			"Define equivalence groups using configuration, software and operating context; identify variations that invalidate equivalence and compare sampled detection with broader coverage.",
			"If choosing sampling, select representative effectively identical resources and evaluate whether it reduces efficiency or effectiveness. Stop relying on sampling where the exception applies.",
			"equivalence-group inventory, configuration/version comparisons, sample selection, detection results and efficiency/effectiveness rationale.",
			"Check omitted resources are effectively identical and the sampling decision does not degrade detection; distinguish permission from a mandatory sampling duty.",
			"A fixed percentage sample without an equivalence or efficiency/effectiveness justification.",
		},
		"VDR-TFR-NMV": {
			"Verify and validate non-machine information resources on their explicit cycle.", "Provider process owners and vulnerability assurance lead",
			"Non-machine-based information resources, including relevant policies, procedures and personnel processes; verify and validate status at least once every 3 months.",
			"Inventory non-machine resources, documented intended operation and owners; define evidence that can establish both verification and validation for each resource type.",
			"Verify and validate non-machine resource status at least once every 3 months; retain actual results and feed detected failures into vulnerability response.",
			"non-machine inventory, intended-operation references, dated verification/validation methods and results, findings and cycle history.",
			"Compare the full non-machine population with both verification and validation records and calculate gaps between executions using months rather than an invented day conversion.",
			"Machine scanning results or a policy approval date presented as verification and validation of all non-machine resources.",
		},
		"VDR-TFR-PDD": {
			"Maintain detection coverage for every information resource likely to drift.", "Provider configuration owner and detection lead",
			"All information resources classified as likely to drift; retain the selected class's explicit interval and SHOULD force, including class applicability decisions.",
			"Classify resources by likelihood of drift and retain the rationale and full drift-prone population. Map each member to detection execution and the selected class schedule.",
			"Persistently detect vulnerabilities on all drift-prone resources at the interval in the selected statement; update classification when operational conditions change.",
			"resource inventory, drift-likelihood determinations, class-specific schedule and dated all-resource detection history with missed cycles and findings.",
			"Reconcile every drift-prone resource to executed detection and assess persistent operation and the exact class interval; a sample alone does not establish this all-resource duty.",
			"A representative sample scan used to claim coverage of all drift-prone resources, or a schedule without executions.",
		},
		"VDR-TFR-PCD": {
			"Keep detection operating for resources that are not likely to drift.", "Provider configuration owner and detection lead",
			"All information resources determined NOT likely to drift, with class-specific intervals separate from drift-prone and sample detection schedules.",
			"Document why resources are not likely to drift and map the full population to detection coverage and the selected class interval.",
			"Persistently perform detection across all non-drifting resources on the selected cycle; revisit the population when immutability or operational assumptions change.",
			"non-drift classification rationale, population revisions, class schedule, dated detection results and gap explanations.",
			"Test the no-drift rationale and reconcile the full population to executions at the correct interval; immutability does not remove the detection recommendation.",
			"A declaration that images are immutable with no repeated detection or missing non-machine resources.",
		},
		"VDR-TFR-PVR": {
			"Reduce potential agency impact within the class- and vulnerability-specific response windows.", "Provider vulnerability response lead and impact evaluator",
			"Evaluated vulnerabilities grouped by current PAIN, internet reachability and likely exploitability for the selected certification class; use the exact source matrix from evaluation. Empty N1 cells supply no numeric deadline.",
			"Locate completed evaluation timestamps, current PAIN, reachability and exploitability decisions and the selected class matrix. Record the initial due-time calculation and how each completed reduction is re-evaluated. The source does not explicitly settle clock resetting after re-evaluation: retain original and subsequent evaluation times and explain the clock interpretation rather than silently restarting it.",
			"Select the correct matrix cell and partially/fully mitigate or remediate to a lower PAIN within that window under the SHOULD rule. Evaluate the actual reduction rather than counting a scheduled patch as reduced impact; retain each rating and timing transition.",
			"vulnerability evaluation timestamps, class and matrix-cell selection, historical/current PAIN and reachability/exploitability decisions, calculated target dates, executed mitigations/remediation and completed impact re-evaluations.",
			"Recalculate each selected window from evaluation, using hours or days exactly as specified; compare completion and evaluated PAIN reductions with targets. Do not invent deadlines for empty cells or treat a mitigation plan as an achieved reduction.",
			"A CVSS-based patch SLA, a single deadline for all classes, or closure without evaluated reduction in agency impact.",
		},
		"VDR-TFR-RMN": {
			"Manage remaining vulnerabilities through provider-determined routine operations.", "Provider vulnerability backlog owner",
			"Remaining vulnerabilities and the provider's determination of necessary mitigation/remediation in routine operations; the rule supplies no additional fixed interval.",
			"Identify the remaining-vulnerability population and the operational criteria used by the provider to determine necessary actions.",
			"Determine and carry out appropriate routine mitigation/remediation under the SHOULD rule, retaining the rationale and disposition for remaining items.",
			"remaining-vulnerability register, provider prioritization/necessity decisions and routine mitigation/remediation records.",
			"Compare operating actions with the provider's stated necessity decisions and identify abandoned or untracked items without inventing a numeric SLA.",
			"A backlog labeled low risk without provider decisions or any evidence of routine management.",
		},
		"VDR-TFR-KEV": {
			"Address KEV remediation dates even when exploitation has already been mitigated.", "Provider KEV response owner",
			"Applicable Known Exploited Vulnerabilities and their CISA KEV Catalog due dates under the cited BOD or successor guidance; full mitigation does not remove this remediation recommendation.",
			"Map KEV entries to affected resource versions and retain each relevant catalog due date and guidance version; distinguish mitigation status from remediation status.",
			"Remediate applicable KEVs according to their catalog due dates under the source SHOULD statement, including fully mitigated KEVs, and verify removal of the vulnerability.",
			"dated KEV catalog entries/due dates, resource applicability mapping, mitigation history, executed remediation and verification results.",
			"Compare actual remediation completion with the relevant KEV due date and confirm mitigated-but-unremediated entries remain visible. The pinned rule does not supply a universal KEV day count.",
			"A firewall mitigation or an unrelated generic patch SLA presented as remediation by the KEV deadline.",
		},
		"VDR-TFR-PSD": {
			"Repeatedly detect vulnerabilities in representative samples of similar machine resources.", "Provider machine detection lead",
			"Representative samples of similar machine-based resources; use the selected class interval and do not replace separate all-resource drift/non-drift obligations.",
			"Identify similar-machine groups, sample membership and representativeness rationale; attach the selected class sample-detection schedule.",
			"Persistently perform vulnerability detection on the representative samples at the class-specific interval and refresh sampling when the population or similarity changes.",
			"machine similarity groups, sample selection history, representativeness rationale, class schedule and dated detection results.",
			"Check sample results are timely and samples represent the claimed machine groups; identify populations or changes not represented by the sample.",
			"A repeatedly scanned test host without a mapping to the similar machine population or proof of representativeness.",
		},
		"VDR-TFR-MVX": {
			"Verify and validate machine resource status on the 20x class-specific cycle.", "Provider 20x machine assurance lead",
			"Machine-based information resources of the 20x offering; the class statement distinguishes SHOULD for A from MUST for B/C and supplies no Class D variant.",
			"Map the machine resource population to intended/documented behavior, verification and validation methods and the explicit 20x class interval.",
			"Execute both verification and validation at the selected interval and retain their results; preserve the unknown-class decision where no explicit class variant exists.",
			"machine inventory, documented intended status, verification/validation executions and results, class schedule and detected failure records.",
			"Reconcile machines to both forms of assurance, calculate actual cycle gaps and distinguish verification of specifications from validation of intended operation.",
			"A vulnerability scan alone, a Rev5 monthly schedule substituted for 20x Class B/C, or an inferred Class D interval.",
		},
		"VDR-TFR-MVF": {
			"Preserve the separate Rev5 machine verification and validation rule.", "Provider Rev5 machine assurance lead",
			"Rev5 machine-based resources: the rule uses monthly verification/validation with SHOULD for B and MUST for C/D; the current 20x inventory excludes this different-type variant.",
			"Map Rev5 machines and intended behavior to verification/validation methods and the source monthly schedule.",
			"When this Rev5 rule applies, verify and validate machine status at least once every month with the selected class force.",
			"Rev5 resource inventory, intended-operation references and monthly verification/validation execution results.",
			"Check type/class selection and both verification and validation; do not import the 20x cycle into the Rev5 rule.",
			"A 20x-only assessment or machine scan lacking separate verification and validation evidence.",
		},
	})
}
